package com.gymmind.course.infrastructure.persistence; import com.gymmind.course.domain.model.Course; import com.gymmind.course.domain.repository.CourseRepository; import org.springframework.stereotype.Repository; import java.util.Optional; @Repository class JpaCourseRepository implements CourseRepository{private final SpringDataCourseRepository d; JpaCourseRepository(SpringDataCourseRepository d){this.d=d;} public Course save(Course c){return d.save(c);} public Optional<Course> findByTenantIdAndId(Long t,Long i){return d.findByTenantIdAndId(t,i);}}
